import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Filter to significant features based on t-test
    sig_features = []
    for i, fid in enumerate(feats.ids):
        if abs(stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i]).statistic) > 2.5:
            sig_features.append(fid)

    # Remove near-duplicates (correlated pairs with |r| >= 0.6)
    correlated_pairs = set()
    for i, fid1 in enumerate(feats.ids):
        for j, fid2 in enumerate(feats.ids[i+1:], i+1):
            if abs(np.corrcoef(feats.x[:,i], feats.x[:,j])[0,1]) >= 0.6:
                correlated_pairs.add((fid1, fid2))

    # Keep one feature from each correlated pair
    keep_features = set(sig_features)
    for fid1, fid2 in correlated_pairs:
        if fid1 in keep_features and fid2 in keep_features:
            keep_features.remove(fid2)  # Remove second one

    # Select top features by effect size
    drivers = []
    for i, fid in enumerate(feats.ids):
        if fid in keep_features:
            t_stat = stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i]).statistic
            drivers.append((abs(t_stat), fid))
    drivers.sort(reverse=True)
    drivers = [fid for _, fid in drivers[:MAX_DRIVERS]]

    # Build logistic regression features
    columns = list(keep_features)
    products = []
    loadings = {}

    # Add interaction terms between top features
    for i, fid1 in enumerate(drivers):
        for j, fid2 in enumerate(drivers[i+1:], i+1):
            products.append((fid1, fid2))

    # Add weighted score from top features
    for fid in drivers:
        idx = feats.column(fid)
        t_stat = stats.ttest_ind(feats.x[feats.y==1, idx], feats.x[feats.y==0, idx]).statistic
        loadings[fid] = t_stat

    return Design(
        drivers=tuple(drivers),
        columns=tuple(columns),
        products=tuple(products),
        loadings=loadings
    )

